def sections_from_headings(apps, schema_editor):
    Category = apps.get_model("library", "Category")
    Section = apps.get_model("library", "Section")
    for category in Category.objects.order_by("position", "name"):
        section, _ = Section.objects.get_or_create(
            pack_id=category.pack_id,
            name=category.section,
            defaults={"position": category.position},
        )
        category.section_ref = section
        category.save(update_fields=["section_ref"])


